import type { LicenseListing, TransferPolicy } from '../types/licex'

export type P2POfferStatus = 'active' | 'pending' | 'completed' | 'cancelled'

export interface NostrLicenseOffer {
  id: string
  nostrEventId: string
  sellerNpub: string
  sellerName: string
  licenseRecordId: string
  listing: LicenseListing
  resalePriceUsdt: number
  /** Swap terms generated by the seller's RGB Lightning node. */
  swapString?: string
  /** Development-only simulated offer; never a real RGB settlement. */
  simulation?: boolean
  royaltyPercent: number
  transferPolicy: TransferPolicy
  transferCount: number
  createdAt: string
  status: P2POfferStatus
}

export interface P2PPaymentSplit {
  totalPaidUsdt: number
  sellerReceivesUsdt: number
  publisherRoyaltyUsdt: number
  licexFeeUsdt: number
  publisherName: string
}

/**
 * Versioned public payload stored in a replaceable Nostr event for a
 * marketplace listing. The event author and `d` tag identify the publisher
 * and stable listing ID; this payload contains only the listing data.
 */
export interface NostrMarketplaceListingPayload {
  schema: 'licex-marketplace-listing'
  version: 1
  listing: LicenseListing
  status: 'published' | 'withdrawn'
}

/** Public Nostr payload for a second-hand license offer in the marketplace. */
export interface NostrMarketplaceResalePayload {
  schema: 'licex-marketplace-resale'
  version: 1
  offer: Omit<NostrLicenseOffer, 'nostrEventId'>
}

/** Public, secret-free signal that a buyer has whitelisted an atomic swap. */
export interface NostrMarketplacePurchaseRequestPayload {
  schema: 'licex-marketplace-purchase-request'
  version: 1
  request: {
    id: string
    offerId: string
    buyerNpub: string
    buyerNodePubkey: string
    createdAt: string
    status: 'pending'
    simulation?: boolean
  }
}

/** Public confirmation tying one completed atomic swap to its buyer request. */
export interface NostrMarketplacePurchaseResultPayload {
  schema: 'licex-marketplace-purchase-result'
  version: 1
  result: {
    requestId: string
    offerId: string
    buyerNpub: string
    buyerNodePubkey: string
    sellerNpub: string
    completedAt: string
    status: 'completed'
    simulation?: boolean
  }
}

export type NostrMarketplacePayload =
  | NostrMarketplaceListingPayload
  | NostrMarketplaceResalePayload
  | NostrMarketplacePurchaseRequestPayload
  | NostrMarketplacePurchaseResultPayload
